<script setup lang="ts">
import {ref,watch} from 'vue';
import {useRouter,useRoute} from 'vue-router';
import {send,state,safeNext,type User} from '../client';
import Challenge from '../components/Challenge.vue';
const props=defineProps<{mode:'login'|'register'}>();const router=useRouter(),route=useRoute();
const email=ref(''),password=ref(''),displayName=ref(''),token=ref(''),busy=ref(false),error=ref('');const challenge=ref<InstanceType<typeof Challenge>>();
watch(()=>props.mode,()=>{token.value='';password.value='';error.value='';});
async function submit(){if(busy.value)return;busy.value=true;error.value='';try{const data=await send<{user:User}>('/api/auth/'+props.mode,{email:email.value,password:password.value,...(props.mode==='register'?{displayName:displayName.value}:{}),captchaToken:token.value});state.user=data.user;await router.replace(safeNext(route.query.next));}catch(e){error.value=(e as Error).message;challenge.value?.reset();}finally{busy.value=false;}}
</script>
<template><main class="auth-page"><section class="auth-context"><div class="eyebrow">YOUR RESEARCH / YOUR WORKSPACE</div><h1>{{mode==='register'?'Start with a question.':'Welcome back.'}}</h1><p>Keep notes, supporting files and a focused watchlist in your own workspace. Publish only what you choose to share.</p><RouterLink to="/research">Browse public research →</RouterLink></section><form class="auth-form" @submit.prevent="submit"><h2>{{mode==='register'?'Create an account':'Sign in'}}</h2><p v-if="!state.config.accountsReady" class="notice">Accounts are temporarily unavailable. Please try again later.</p><label v-if="mode==='register'">Display name<input v-model="displayName" name="name" autocomplete="nickname" required maxlength="80"></label><label>Email<input v-model="email" name="email" type="email" autocomplete="username" required maxlength="254"></label><label>Password<input v-model="password" name="password" type="password" :autocomplete="mode==='register'?'new-password':'current-password'" minlength="12" maxlength="128" required></label><p class="hint">Use 12–128 characters. Keep a copy in your password manager.</p><Challenge :key="mode" ref="challenge" :action="mode" @update:token="token=$event"/><p v-if="error" class="error" role="alert">{{error}}</p><button class="primary" type="submit" :disabled="busy||!token||!state.config.accountsReady">{{busy?'Please wait…':mode==='register'?'Create account':'Sign in'}}</button><p class="auth-switch"><RouterLink v-if="mode==='login'" to="/register">Create an account →</RouterLink><RouterLink v-else to="/login">Already registered? Sign in →</RouterLink></p></form></main></template>
